ge-enter-active 260ms / .page-leave-active 140ms / .page-enter-from 带 clip-path\n */\n\n/* ── 令牌：白天是纸白杂志，系统偏好深色时整页翻成夜版 ───────────────── */\n\n.opening-shell {\n  --fq-bg: #f5f3ee;\n  --fq-panel: #fffefb;\n  --fq-panel-2: #f0ede6;\n  --fq-ink: #101016;\n  --fq-ink-soft: #3b3b45;\n  --fq-ink-faint: #6a6a76;\n  --fq-line: rgba(16, 16, 22, 0.26);\n  --fq-rule: rgba(16, 16, 22, 0.14);\n  --fq-hairline: rgba(16, 16, 22, 0.09);\n  --fq-accent: #d61a38;\n  --fq-accent-ink: #b3142d;\n  /* 白字实底块用加深一档的猩红：白字要够 4.5:1 */\n  --fq-fill: #d61a38;\n  --fq-accent-wash: rgba(214, 26, 56, 0.08);\n  --fq-ok: #157a5b;\n  --fq-hard: 6px 6px 0 rgba(16, 16, 22, 0.18);\n  --fq-hard-sm: 3px 3px 0 rgba(16, 16, 22, 0.16);\n  --fq-mono: ui-monospace, 'SF Mono', 'JetBrains Mono', 'Roboto Mono', Menlo, Consolas, monospace;\n  --fq-sans: 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', system-ui, sans-serif;\n\n  position: relative;\n  isolation: isolate;\n  width: min(100%, 820px);\n  min-height: 100vh;\n  margin: 0 auto;\n  padding: 34px 26px 26px;\n  background: var(--fq-bg);\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n}\n\n@media (prefers-color-scheme: dark) {\n  .opening-shell {\n    --fq-bg: #08080b;\n    --fq-panel: #121218;\n    --fq-panel-2: #0b0b10;\n    --fq-ink: #f4f2ec;\n    --fq-ink-soft: #c8c5cf;\n    --fq-ink-faint: #8b8896;\n    --fq-line: rgba(244, 242, 236, 0.26);\n    --fq-rule: rgba(244, 242, 236, 0.14);\n    --fq-hairline: rgba(244, 242, 236, 0.09);\n    --fq-accent: #ff3b5c;\n    --fq-accent-ink: #ff5a75;\n    --fq-fill: #e01b3f;\n    --fq-accent-wash: rgba(255, 59, 92, 0.12);\n    --fq-ok: #6fd3b0;\n    --fq-hard: 6px 6px 0 rgba(0, 0, 0, 0.55);\n    --fq-hard-sm: 3px 3px 0 rgba(0, 0, 0, 0.5);\n  }\n}\n\n* {\n  box-sizing: border-box;\n}\n\nbutton,\ninput,\nselect,\ntextarea {\n  font: inherit;\n}\n\nbutton {\n  cursor: pointer;\n}\n\nh1,\nh2,\nh3,\np {\n  overflow-wrap: anywhere;\n}\n\n/* 上一版的环境装饰一律拆掉：不留漂浮圆环、不留花饰 */\n.ambient,\n.ornament-top {\n  display: none;\n}\n\n/* ── 刊头 ───────────────────────────────────────────────────────────── */\n\n.opening-header {\n  display: flex;\n  align-items: flex-start;\n  gap: 16px;\n  min-width: 0;\n  padding: 0 0 18px;\n  border-bottom: 2px solid var(--fq-ink);\n}\n\n/* 编号方块：猩红实底 + 等宽白字，代替原来的花饰图标 */\n.brand-mark {\n  position: relative;\n  flex: 0 0 44px;\n  width: 44px;\n  height: 44px;\n  background: var(--fq-accent);\n  color: #fff;\n\n  &::after {\n    content: 'N°01';\n    position: absolute;\n    inset: 0;\n    display: grid;\n    place-items: center;\n    font-family: var(--fq-mono);\n    font-size: 11px;\n    font-weight: 700;\n    letter-spacing: 0.04em;\n  }\n\n  /* 方块里的旧装饰全部收起来 */\n  .brand-star,\n  .brand-ring,\n  .brand-heart {\n    display: none;\n  }\n}\n\n.brand-copy {\n  min-width: 0;\n}\n\n.eyebrow {\n  margin: 0 0 6px;\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.18em;\n  line-height: 1.4;\n  text-transform: uppercase;\n}\n\nh1 {\n  margin: 0;\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 38px;\n  font-weight: 900;\n  line-height: 1.02;\n  letter-spacing: -0.03em;\n}\n\n.subtitle {\n  margin: 8px 0 0;\n  max-width: 44ch;\n  color: var(--fq-ink-faint);\n  font-size: 12px;\n  line-height: 1.7;\n}\n\n.world-note {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  margin-left: auto;\n  padding: 4px 0 0;\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  line-height: 1.3;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n  white-space: nowrap;\n}\n\n.note-dot {\n  width: 6px;\n  height: 6px;\n  background: var(--fq-accent);\n}\n\n/* ── 步骤条：页码 + 文字 ─────────────────────────────────────────────── */\n\n.stepper {\n  display: flex;\n  gap: 0;\n  margin: 0;\n  padding: 0;\n  border-bottom: 1px solid var(--fq-line);\n  background: transparent;\n  overflow: visible;\n}\n\n.step-item {\n  display: flex;\n  flex: 1 1 0;\n  align-items: center;\n  justify-content: flex-start;\n  gap: 8px;\n  min-width: 0;\n  min-height: 46px;\n  padding: 10px 12px 11px;\n  border: 0;\n  border-right: 1px solid var(--fq-hairline);\n  border-bottom: 2px solid transparent;\n  background: transparent;\n  color: var(--fq-ink-faint);\n  font-size: 11.5px;\n  position: relative;\n  transition: color 0.12s linear, border-color 0.12s linear, background 0.12s linear;\n\n  &:last-child {\n    border-right: 0;\n  }\n\n  &:hover,\n  &:focus-visible {\n    color: var(--fq-ink);\n    outline: none;\n    background: var(--fq-hairline);\n  }\n\n  &.active {\n    color: var(--fq-ink);\n    border-bottom-color: var(--fq-accent);\n    background: transparent;\n  }\n\n  &.done {\n    color: var(--fq-ink-soft);\n  }\n}\n\n/* 页码：等宽，选中时转猩红 */\n.step-number {\n  flex: 0 0 auto;\n  font-family: var(--fq-mono);\n  font-size: 11px;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n  color: var(--fq-ink-faint);\n  border: 0;\n  background: none;\n  padding: 0;\n  width: auto;\n  height: auto;\n}\n\n.step-item.active .step-number {\n  color: var(--fq-accent);\n}\n\n.step-item.done .step-number {\n  color: var(--fq-ok);\n}\n\n.step-label {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n}\n\n/* ── 问卷面板 ───────────────────────────────────────────────────────── */\n\n.form-panel,\n.locked-panel {\n  position: relative;\n  border: 1px solid var(--fq-line);\n  background: var(--fq-panel);\n  box-shadow: none;\n}\n\n.form-panel {\n  padding: 28px 30px 20px;\n  border-radius: 0;\n}\n\n.panel-heading {\n  display: flex;\n  align-items: flex-start;\n  justify-content: space-between;\n  gap: 20px;\n  padding-bottom: 16px;\n  border-bottom: 1px solid var(--fq-line);\n}\n\n.panel-heading h2,\n.locked-panel h2 {\n  margin: 0;\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 30px;\n  font-weight: 900;\n  line-height: 1.16;\n  letter-spacing: -0.025em;\n}\n\n.heading-description {\n  max-width: 46ch;\n  margin: 10px 0 0;\n  color: var(--fq-ink-faint);\n  font-size: 12px;\n  line-height: 1.7;\n}\n\n/* 页码读数：等宽大数字 + 总页数 */\n.page-count {\n  flex: 0 0 auto;\n  display: flex;\n  align-items: baseline;\n  gap: 4px;\n  padding: 0;\n  border: 0;\n  border-radius: 0;\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  white-space: nowrap;\n}\n\n.page-count strong {\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n  font-size: 28px;\n  font-weight: 700;\n  letter-spacing: -0.02em;\n  line-height: 1;\n}\n\n.page-count span {\n  font-size: 11px;\n  letter-spacing: 0.08em;\n}\n\n.step-content {\n  min-height: 430px;\n  padding-top: 22px;\n  clip-path: inset(0);\n}\n\n/* 段落导语：前面一个大序号，后面一句话 */\n.section-intro {\n  display: flex;\n  align-items: baseline;\n  gap: 14px;\n  margin-bottom: 26px;\n  padding-bottom: 12px;\n  border-bottom: 1px solid var(--fq-hairline);\n  color: var(--fq-ink-soft);\n  font-size: 12px;\n  line-height: 1.7;\n}\n\n.section-intro p {\n  max-width: 54ch;\n  margin: 0;\n}\n\n.section-symbol {\n  flex: 0 0 auto;\n  width: auto;\n  height: auto;\n  border: 0;\n  border-radius: 0;\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n  font-size: 28px;\n  font-weight: 700;\n  line-height: 0.9;\n  letter-spacing: -0.03em;\n}\n\n/* ── 字段 ───────────────────────────────────────────────────────────── */\n\n.field-grid {\n  display: grid;\n  gap: 18px;\n}\n\n.two-columns {\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  column-gap: 26px;\n}\n\n/* 两栏之间只留一道 1px 竖线，不是骑缝虚线 */\n.two-columns > *:nth-child(odd) {\n  border-right: 1px solid var(--fq-hairline);\n  padding-right: 26px;\n}\n\n.two-columns > *:nth-child(even) {\n  padding-right: 0;\n}\n\n.field,\n.static-field {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  gap: 2px;\n}\n\n/* 字段名＝等宽全大写小标签 */\n.field > span,\n.static-field > span {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.14em;\n  text-transform: uppercase;\n}\n\n.field b {\n  color: var(--fq-accent);\n  font-weight: 700;\n  font-size: 11px;\n}\n\n.field em {\n  margin-left: 5px;\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  font-style: normal;\n  font-weight: 400;\n}\n\n/* 输入一律下划线式：没有边框盒子 */\n.field input,\n.field select,\n.field textarea {\n  width: 100%;\n  min-width: 0;\n  border: 0;\n  border-bottom: 1px solid var(--fq-line);\n  border-radius: 0;\n  background: transparent;\n  color: var(--fq-ink);\n  font-size: 14px;\n  line-height: 1.5;\n  outline: none;\n  box-shadow: none;\n  transition: border-color 0.12s linear, background 0.12s linear;\n}\n\n.field input,\n.field select {\n  min-height: 38px;\n  padding: 7px 2px;\n}\n\n.field textarea {\n  min-height: 82px;\n  resize: vertical;\n  padding: 8px 2px;\n}\n\n.field input::placeholder,\n.field textarea::placeholder {\n  color: var(--fq-ink-faint);\n  opacity: 0.7;\n}\n\n.field input:focus,\n.field select:focus,\n.field textarea:focus {\n  border-bottom-color: var(--fq-accent);\n  background: transparent;\n}\n\n.field small,\n.static-field small {\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  font-weight: 400;\n  line-height: 1.6;\n}\n\n.field-count {\n  align-self: flex-end;\n  margin-top: 2px;\n  font-family: var(--fq-mono);\n  letter-spacing: 0.06em;\n}\n\n.identity-row {\n  margin-top: 18px;\n}\n\n/* 只读格：左侧 2px 猩红竖条，不用绿色 */\n.static-field {\n  justify-content: center;\n  min-height: 78px;\n  padding: 8px 0 8px 14px;\n  border-left: 2px solid var(--fq-accent);\n  background: transparent;\n}\n\n.static-field strong {\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 16px;\n  font-weight: 800;\n  letter-spacing: -0.01em;\n}\n\n/* ── 小节标题 ───────────────────────────────────────────────────────── */\n\n.subsection-heading {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin: 26px 0 14px;\n  padding-bottom: 8px;\n  border-bottom: 2px solid var(--fq-ink);\n}\n\n.subsection-heading h3 {\n  margin: 0;\n  color: var(--fq-ink);\n  font-family: var(--fq-sans);\n  font-size: 16px;\n  font-weight: 800;\n  letter-spacing: -0.01em;\n  white-space: nowrap;\n  position: relative;\n  padding-left: 12px;\n\n  &::before {\n    content: '';\n    position: absolute;\n    left: 0;\n    top: 50%;\n    transform: translateY(-50%);\n    width: 3px;\n    height: 0.9em;\n    background: var(--fq-accent);\n  }\n}\n\n.subsection-heading em {\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  font-style: normal;\n  font-weight: 400;\n  letter-spacing: 0.1em;\n}\n\n.interest-count {\n  margin-left: auto;\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  letter-spacing: 0.1em;\n  white-space: nowrap;\n}\n\n.interest-count.full {\n  color: var(--fq-accent);\n}\n\n.tiny-line {\n  display: block;\n  width: 18px;\n  height: 2px;\n  background: var(--fq-accent);\n}\n\n/* ── 选项：硬边方片，选中＝猩红实底 ──────────────────────────────── */\n\n.choice-row,\n.chip-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.choice-note {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  margin: 12px 0 0;\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  line-height: 1.6;\n}\n\n.choice-note span {\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n  font-size: 11px;\n}\n\n.choice-pill,\n.talent-chip,\n.preset-button {\n  border: 1px solid var(--fq-line);\n  border-radius: 0;\n  background: transparent;\n  color: var(--fq-ink-soft);\n  font-size: 11.5px;\n  transition: border-color 0.12s linear, color 0.12s linear, background 0.12s linear;\n}\n\n.choice-pill:hover,\n.choice-pill:focus-visible,\n.talent-chip:hover:not(:disabled),\n.talent-chip:focus-visible:not(:disabled),\n.preset-button:hover,\n.preset-button:focus-visible {\n  border-color: var(--fq-accent);\n  color: var(--fq-accent);\n  background: var(--fq-accent-wash);\n  outline: none;\n}\n\n.choice-pill {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-height: 38px;\n  padding: 7px 12px;\n}\n\n/* 选中：整块反色（猩红实底 + 白字） */\n.choice-pill.selected,\n.talent-chip.selected,\n.preset-button.selected {\n  border-color: var(--fq-fill);\n  background: var(--fq-fill);\n  color: #ffffff;\n  font-weight: 700;\n}\n\n.pill-mark {\n  color: currentColor;\n  font-family: var(--fq-mono);\n  font-size: 11px;\n}\n\n/* ── 能力分配 ───────────────────────────────────────────────────────── */\n\n.ability-intro {\n  position: relative;\n  padding-right: 0;\n}\n\n.points-meter {\n  position: relative;\n  flex: 0 0 auto;\n  margin-left: auto;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  justify-content: flex-end;\n  gap: 3px;\n  width: auto;\n  min-width: 64px;\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n}\n\n.points-meter strong {\n  font-family: var(--fq-mono);\n  font-size: 26px;\n  font-weight: 700;\n  line-height: 1;\n}\n\n.points-meter span {\n  align-self: flex-end;\n  padding-bottom: 2px;\n  color: var(--fq-ink-faint);\n  font-size: 11px;\n}\n\n.points-meter small {\n  flex-basis: 100%;\n  color: var(--fq-ink-faint);\n  font-size: 9px;\n  letter-spacing: 0.08em;\n  text-align: right;\n}\n\n.preset-strip {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 6px;\n  padding: 10px 0;\n  border-top: 1px solid var(--fq-hairline);\n  border-bottom: 1px solid var(--fq-hairline);\n  background: transparent;\n}\n\n.preset-label {\n  margin-right: 4px;\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  letter-spacing: 0.12em;\n  text-transform: uppercase;\n}\n\n.preset-button {\n  min-height: 27px;\n  padding: 4px 9px;\n}\n\n.ability-list {\n  margin-top: 16px;\n  border-top: 1px solid var(--fq-hairline);\n}\n\n.ability-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  min-width: 0;\n  padding: 13px 0;\n  border-bottom: 1px solid var(--fq-hairline);\n  transition: background 0.12s linear;\n}\n\n.ability-row:hover {\n  background: var(--fq-accent-wash);\n}\n\n.ability-copy {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  gap: 3px;\n}\n\n.ability-copy strong {\n  color: var(--fq-ink);\n  font-size: 13px;\n  font-weight: 700;\n}\n\n.ability-copy span {\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  line-height: 1.5;\n}\n\n.ability-control {\n  display: flex;\n  align-items: center;\n  flex: 0 0 auto;\n  gap: 6px;\n}\n\n.stepper-button {\n  display: grid;\n  place-items: center;\n  width: 28px;\n  height: 28px;\n  border: 1px solid var(--fq-line);\n  border-radius: 0;\n  background: transparent;\n  color: var(--fq-ink);\n  font-family: var(--fq-mono);\n  font-size: 16px;\n  line-height: 1;\n  transition: background 0.12s linear, color 0.12s linear, opacity 0.12s linear;\n}\n\n.stepper-button:hover:not(:disabled),\n.stepper-button:focus-visible:not(:disabled) {\n  background: var(--fq-fill);\n  border-color: var(--fq-fill);\n  color: #fff;\n  outline: none;\n}\n\n.stepper-button:disabled {\n  cursor: not-allowed;\n  opacity: 0.3;\n}\n\n.ability-value {\n  display: grid;\n  place-items: center;\n  width: 26px;\n  color: var(--fq-ink);\n  font-family: var(--fq-mono);\n  font-size: 17px;\n  font-weight: 700;\n  font-variant-numeric: tabular-nums;\n}\n\n.ability-value.level-high {\n  color: var(--fq-accent);\n}\n\n.ability-note {\n  margin-top: 16px;\n  padding: 9px 0 9px 12px;\n  border-left: 2px solid var(--fq-line);\n  background: transparent;\n  color: var(--fq-ink-faint);\n  font-size: 10px;\n  line-height: 1.7;\n}\n\n.ability-note span {\n  margin-right: 5px;\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n  font-size: 13px;\n}\n\n/* ── 特长 / 兴趣 ────────────────────────────────────────────────────── */\n\n.talent-block {\n  margin-bottom: 22px;\n}\n\n.left-heading {\n  justify-content: flex-start;\n  margin-top: 0;\n  margin-bottom: 12px;\n}\n\n.talent-group {\n  display: flex;\n  align-items: flex-start;\n  gap: 12px;\n  margin: 8px 0;\n}\n\n.group-label {\n  flex: 0 0 62px;\n  padding-top: 8px;\n  color: var(--fq-ink-faint);\n  font-family: var(--fq-mono);\n  font-size: 9.5px;\n  line-height: 1.4;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n}\n\n.talent-chip {\n  min-height: 28px;\n  padding: 4px 10px;\n}\n\n.talent-chip:disabled {\n  cursor: not-allowed;\n  opacity: 0.4;\n}\n\n.compact-field {\n  margin: 14px 0 0 74px;\n  max-width: 360px;\n}\n\n/* ── 开场情境 ───────────────────────────────────────────────────────── */\n\n.scene-heading {\n  margin-top: 28px;\n}\n\n.scene-grid {\n  display: grid;\n  grid-template-columns: repeat(3, minmax(0, 1fr));\n  gap: 8px;\n  counter-reset: scene;\n}\n\n.scene-option {\n  counter-increment: scene;\n  position: relative;\n  display: flex;\n  align-items: flex-start;\n  gap: 9px;\n  min-width: 0;\n  min-height: 104px;\n  padding: 13px 11px;\n  border: 1px solid var(--fq-line);\n  border-radius: 0;\n  background: transparent;\n  color: var(--fq-ink);\n  text-align: left;\n  transition: border-color 0.12s linear, background 0.12s linear;\n\n  &:hover,\n  &:focus-visible {\n    border-color: var(--fq-accent);\n    background: var(--fq-accent-wash);\n    outline: none;\n  }\n\n  &.selected {\n    border-color: var(--fq-accent);\n    background: var(--fq-accent-wash);\n    box-shadow: inset 3px 0 0 0 var(--fq-accent);\n  }\n}\n\n.scene-glyph {\n  display: none;\n}\n\n.scene-option::before {\n  content: counter(scene, decimal-leading-zero);\n  flex: 0 0 auto;\n  color: var(--fq-accent);\n  font-family: var(--fq-mono);\n  font-size: 11px;\n  font-weight: 700;\n  line-height: 1.7;\n}\n\n.scene-text {\n  display: flex;\n  flex-direction: column;\n  min-width: 0;\n  gap: 5px;\n}\n\n.scene-text strong {\n  font-size: 12.5px;\n  font-weight: 800;\n}\n\n.scene-text small {\n  color: var(--fq-ink-faint);\