gap: 10px;\n  min-width: 132px;\n  padding: 10px 18px;\n  border: 1px solid var(--fq-fill);\n  background: var(--fq-fill);\n  color: #fff;\n  font-family: var(--fq-sans);\n  font-size: 12.5px;\n  font-weight: 800;\n  letter-spacing: 0.12em;\n  box-shadow: var(--fq-hard-sm);\n}\n\n.primary-button:hover:not(:disabled),\n.primary-button:focus-visible:not(:disabled) {\n  background: var(--fq-ink);\n  border-color: var(--fq-ink);\n  color: var(--fq-bg);\n  outline: none;\n}\n\n.primary-button:active:not(:disabled) {\n  transform: translate(2px, 2px);\n  box-shadow: none;\n}\n\n.primary-button:disabled {\n  cursor: wait;\n  opacity: 0.6;\n}\n\n.button-arrow {\n  font-family: var(--fq-mono);\n  font-size: 15px;\n}\n\n.button-loader {\n  width: 13px;\n  height: 13px;\n  border: 1px solid rgba(255, 255, 255, 0.45);\n  border-top-color: #fff;\n  border-radius: 0;\n  animation: spin 0.8s linear infinite;\n}\n\n.action-spacer {\n  width: 1px;\n}\n\n.form-alert {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  margin-top: 16px;\n  padding: 9px 0 9px 12px;\n  border-left: 3px solid var(--fq-accent);\n  background: var(--fq-accent-wash);\n  color: var(--fq-accent-ink);\n  font-size: 11px;\n  line-height: 1.55;\n}\n\n.form-alert > span {\n  display: grid;\n  place-items: center;\n  flex: 0 0 16px;\n  width: 16px;\n  height: 16px;\n  border: 1px solid currentColor;\n  border-radius: 0;\n  font-family: var(--fq-mono);\n  font-size: 10px;\n  font-weight: 700;\n}\n\n/* ── 已提交面板 ─────────────────────────────────────────────────────── */\n\n.locked-panel {\n  padding: 54px 30px;\n  text-align: center;\n  border-top: 2px solid var(--fq-ink);\n}\n\n.locked-symbol {\n  display: grid;\n  place-items: center;\n  width: 46px;\n  height: 46px;\n  margin: 0 auto 18px;\n  border: 0;\n  border-radius: 0;\n  background: var(--fq-fill);\n  color: #fff;\n  font-family: var(--fq-mono);\n  font-size: 20px;\n}\n\n.locked-panel h2 {\n  margin-top: 8px;\n}\n\n.locked-panel > p:not(.eyebrow):not(